WITH warehouse_page_sales AS ( SELECT w.w_warehouse_id, w.w_city, wp.wp_type, hd.hd_buy_potential, SUM(ws.ws_net_paid) AS total_net_paid FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk GROUP BY w.w_warehouse_id, w.w_city, wp.wp_type, hd.hd_buy_potential ) SELECT w_warehouse_id, w_city, wp_type, hd_buy_potential, total_net_paid, CASE WHEN total_net_paid >= 500000 THEN 'Platinum' WHEN total_net_paid >= 200000 THEN 'Gold' WHEN total_net_paid >= 50000 THEN 'Silver' ELSE 'Bronze' END AS revenue_tier, ROW_NUMBER() OVER (PARTITION BY w_warehouse_id ORDER BY total_net_paid DESC) AS page_type_rank FROM warehouse_page_sales ORDER BY w_warehouse_id, page_type_rank LIMIT 100
